<?php

// OPcache preload entry point, enabled by frankenphp/conf.d/app.prod.ini (production image only).
// The file below is generated by `cache:warmup`/`cache:clear` (APP_ENV=prod) and lists the
// framework/container classes worth preloading.

if (file_exists(dirname(__DIR__).'/var/cache/prod/App_KernelProdContainer.preload.php')) {
    require dirname(__DIR__).'/var/cache/prod/App_KernelProdContainer.preload.php';
}
